ltac2:(KReplay.run1 (kr_t_PnMpRiKit ()) ["WithHeap"] (Mh_0186_blobs1.kr_b_040 ())). Qed.
Lemma ec_state_agree M M' o (bb : bool) c : L5C.agree_on M M' o 16 -> 0 <= o -> o + 16 <= 2 ^ 64 -> NEM.ec_state RSEGS AD M o bb c -> NEM.ec_state RSEGS AD M' o bb c.
