Lemma ALs : (fb + 32) mod 8 = 0 /\ (fb + 432) mod 8 = 0 /\ (fb + 8) mod 8 = 0 /\ (fb + 616) mod 8 = 0.
Proof.
ltac2:(KReplay.run1 (kr_t_PnMpRiA ()) ["WithHeap"; "Call"] (Mh_0186_blobs1.kr_b_281 ())). Qed.

(* [comment removed for export] *)
Definition AT (R1 : bvmap 5 word) (M1 : word -> option byte) (s1 : PQM.mpst) (sm1 : PM.strm) (t : Z) : Prop :=
  getr R1 (PMK.reg 2) = Z_to_bv 64 (sp - 144) /\ getr R1 (PMK.reg 8) = Z_to_bv 64 (fb + 32) /\ getr R1 (PMK.reg 9) = Z_to_bv 64 (fb + 8)
  /\ getr R1 (PMK.reg 18) = Z_to_bv 64 (fb + 432) /\ getr R1 (PMK.reg 19) = Z_to_bv 64 (fb + 32 + 24) /\ getr R1 (PMK.reg 10) = Z_to_bv 64 1
  /\ (forall x, In x [3; 4; 22; 23; 24; 25; 26; 27]%nat -> getr R1 (PMK.reg x) = getr R (PMK.reg x))
  /\ RS 1 M1 s1 sm1 e cr model /\ L5.u8_at RSEGS M1 (sp - 57) t /\ 0 <= t < 256.

