Local Ltac arm_qv QVL R2 R3 RP3 KS2 X2 X8 X9 X18 XS :=
  first [ (rewrite (PMK.cs_of_preserved R2 R3 2 RP3) by PMK.inl; rewrite (KS2 2%nat) by PMK.inl; exact X2)
        | (rewrite (PMK.cs_of_preserved R2 R3 8 RP3) by PMK.inl; rewrite (KS2 8%nat) by PMK.inl; exact X8)
        | (rewrite (PMK.cs_of_preserved R2 R3 9 RP3) by PMK.inl; rewrite (KS2 9%nat) by PMK.inl; exact X9)
        | (rewrite (PMK.cs_of_preserved R2 R3 18 RP3) by PMK.inl; rewrite (KS2 18%nat) by PMK.inl; exact X18)
        | (let x := fresh "x" in let Hx := fresh "Hx" in intros x Hx;
           rewrite (PMK.cs_of_preserved R2 R3 x RP3) by (cbn in Hx; repeat (destruct Hx as [<-|Hx]; [PMK.inl|]); destruct Hx);
           rewrite (KS2 x) by (cbn in Hx; repeat (destruct Hx as [<-|Hx]; [PMK.inl|]); destruct Hx); apply XS; exact Hx)
        | lia | assumption ].

