Lemma ARM_N_post (fx1 fx2 : FPState) (R1 R2 : bvmap 5 word) (M1 : word -> option byte) (s1 : PQM.mpst) (sm1 : PM.strm) (t v : Z) :
  PNV.v_int64_spec RSEGS AD AQ AE L HI -> AT R1 M1 s1 sm1 t ->
  msteps RSEGS (@mkst fx1 R1 (Z_to_bv 64 0x45804) M1 (seg_rom RSEGS)) (@mkst fx2 R2 (Z_to_bv 64 0x3a15c) M1 (seg_rom RSEGS)) ->
  (forall x, In x [2; 3; 4; 8; 9; 18; 22; 23; 24; 25; 26; 27]%nat -> getr R2 (PMK.reg x) = getr R1 (PMK.reg x)) ->
  getr R2 (PMK.reg 1) = Z_to_bv 64 0x45860 -> getr R2 (PMK.reg 10) = Z_to_bv 64 (fb + 432) ->
  getr R2 (PMK.reg 11) = Z_to_bv 64 v -> 2 ^ 64 - 32 <= v < 2 ^ 64 ->
  getr R2 (PMK.reg 12) = Z_to_bv 64 0 -> getr R2 (PMK.reg 14) = Z_to_bv 64 (fb + 8) ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx1 R1 0x45804 M1 model) K.
Proof.
ltac2:(KReplay.run1 (kr_t_PnMpRiA ()) ["WithHeap"; "Call"] (Mh_0186_blobs1.kr_b_292 ())). Qed.

