Definition RGE (M2 : word -> option byte) (s2 : PQM.mpst) (st2 : NEM.aest) (sm2 : PM.strm) (e2 : bool) (cr2 : credit) (model2 : Model) : Prop :=
  PNRN.mrun_fin RSEGS AD AQ AE L M2 fb s2 st2 str sm2 e2 true cat /\ PMSP.src_step (PQM.p_src s) (PQM.p_src s2) sm sm2 /\ (e = true -> e2 = true)
  /\ PQM.p_more s2 = 0
  /\ saved M2 /\ cm M2 /\ PMSP.credit_keep cr cr2 (PNRN.pot_run L s st) (PNRN.pot_run L s2 st2) /\ model_but_vm model model2
  /\ hi_heap HI (PNRN.mown s2 st2 ++ LBX) cr2 M2 (m_vmmaps model2).
