(* [comment removed for export] *)
Lemma SPAN (rr len c : Z) (fx1 : FPState) (R1 : bvmap 5 word) (M1 : word -> option byte) (model1 : Model)
      (s1 : PQM.mpst) (sm1 : PM.strm) (e1 : bool) (cr1 : credit) :
  PQV8.read_span_v_specG RSEGS AD L HI 0x46804 ->
  getr R1 (PMK.reg 1) = Z_to_bv 64 rr -> L5.ra_ok rr -> getr R1 (PMK.reg 2) = Z_to_bv 64 (sp - 144) ->
  getr R1 (PMK.reg 10) = Z_to_bv 64 (op + 24) -> getr R1 (PMK.reg 11) = Z_to_bv 64 len -> getr R1 (PMK.reg 12) = Z_to_bv 64 (op + 352) ->
  0 <= len < 2 ^ 64 ->
  getr R1 (PMK.reg 3) = getr R (PMK.reg 3) -> getr R1 (PMK.reg 4) = getr R (PMK.reg 4) ->
  0 <= c -> RS c M1 s1 sm1 e1 cr1 model1 ->
  (forall (fx2 : FPState) (R2 : bvmap 5 word) (M2 : word -> option byte) (model2 : Model) (s2 : PQM.mpst) (sm2 : PM.strm) (cr2 : credit) (ptr k : Z),
     regs_preserved R1 R2 -> getr R2 (PMK.reg 10) = Z_to_bv 64 ptr -> getr R2 (PMK.reg 11) = Z_to_bv 64 k -> 0 <= k <= len -> k < 2 ^ 26 ->
     ((ptr = 0 /\ k = 0) \/ PGS.in_blk (PQM.mparser_own s2) ptr k) -> L5.defined M2 ptr k ->
     PQM.p_stk s2 = PQM.p_stk s1 -> PQM.p_more s2 = PQM.p_more s1 ->
     RS (c + k) M2 s2 sm2 e1 cr2 model2 ->
     (forall a m, sp - 144 <= a -> a + m <= sp -> L5C.agree_on M1 M2 a m) ->
     srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx2 R2 rr M2 model2) K) ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx1 R1 0x46804 M1 model1) K.
Proof.
ltac2:(KReplay.run1 (kr_tL_Mh_0186 ()) ["WithHeap"; "Call"] (Mh_0186_blobs1.kr_b_422 ())). Qed.

