      (s1 : PQM.mpst) (sm1 : PM.strm) (e1 : bool) (cr1 : credit) (l : list Z) :
  PECVS.validate_fun_spec RSEGS AD L (pa_validate AD) ->
  getr R1 (PMK.reg 1) = Z_to_bv 64 rr -> L5.ra_ok rr -> getr R1 (PMK.reg 2) = Z_to_bv 64 (sp - 144) ->
  getr R1 (PMK.reg 10) = Z_to_bv 64 p -> getr R1 (PMK.reg 11) = Z_to_bv 64 k -> 0 <= k < 2 ^ 26 -> 0 <= p -> (k = 0 \/ 0 < p) -> p + k <= 2 ^ 47 ->
  L5.defined M1 p k -> (k = 0 \/ sp - 144 <= p \/ p + k <= sp - 144 - 12288) ->
  getr R1 (PMK.reg 3) = getr R (PMK.reg 3) -> getr R1 (PMK.reg 4) = getr R (PMK.reg 4) ->
  0 <= c -> RS c M1 s1 sm1 e1 cr1 model1 ->
