  (forall (fx2 : FPState) (R2 : bvmap 5 word) (M2 : word -> option byte) (v : Z),
     regs_preserved R1 R2 -> mem_grows M1 M2 ->
     (forall i, 0 <= i < 2 ^ 64 -> ~ (sp - 144 - 12288 <= i < sp - 144) -> M2 (Z_to_bv 64 i) = M1 (Z_to_bv 64 i)) ->
     getr R2 (PMK.reg 11) = Z_to_bv 64 v -> 0 <= v < 7 -> (v = 0 <-> utf8_valid l = true) ->
     RS c M2 s1 sm1 e1 cr1 model1 -> srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx2 R2 rr M2 model1) K) ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx1 R1 0x468cc M1 model1) K.
