Local Ltac rifeed := first [ PMK.sc | unfold PQRIPH.aligned, PQRIPE.aligned, PQRIPT.aligned; first [ assumption | lia ] ].
Local Ltac ksx KS XS n := rewrite (KS n) by PMK.inl; apply XS; PMK.inl.
Local Ltac cs2 Ra Rb RP KS n X := rewrite (PMK.cs_of_preserved Ra Rb n RP) by PMK.inl; rewrite (KS n) by PMK.inl; exact X.
Local Ltac csx Ra Rb RP KS XS :=
  let x := fresh "x" in let Hx := fresh "Hx" in intros x Hx;
  rewrite (PMK.cs_of_preserved Ra Rb x RP) by (cbn in Hx; repeat (destruct Hx as [<-|Hx]; [PMK.inl|]); destruct Hx);
  rewrite (KS x) by (cbn in Hx; repeat (destruct Hx as [<-|Hx]; [PMK.inl|]); destruct Hx); apply XS; exact Hx.
Local Ltac rs_facts RS1 PA1 AA1 OT1 SV1 CM1 EC1 STK1 WR1 BA1 IMG1 PD1 W8 AV1 M1 :=
  pose proof RS1 as ((PA1 & AA1 & OT1 & _ & _ & _ & _ & _ & _ & SV1 & CM1 & _) & EC1);
  pose proof CM1 as (_ & _ & STK1); pose proof (L5C.stk_writable RSEGS _ M1 sp PQRIK.SCR STK1) as WR1;
  pose proof OT1 as (_ & _ & BA1 & _); pose proof BA1 as (IMG1 & _); cbn [pa_rw_lo AD PnLayoutS.ADDR_S] in IMG1;
  pose proof PA1 as (_ & PD1 & _); pose proof AA1 as ((AV1 & _) & _);
  assert (W8 : L5.writable RSEGS M1 (fb + 32 + 8) 1) by (apply (L5C.writable_of_defined RSEGS); [apply (L5.defined_sub M1 (fb + 32) 400); [exact PD1|lia|lia]|lia|lia]);
  unfold PQRIK.oa in AV1; cbn [qa_vp_adaptor AQ PnLayoutQS.QADDR_S] in AV1.
