Lemma ERF_TAIL (len et : Z) (e1 : bool) (fx2 : FPState) (R2 : bvmap 5 word) (M2 : word -> option byte) (model2 : Model)
      (s2 : PQM.mpst) (sm2 : PM.strm) (cr2 : credit) (ptr k : Z) :
  PNV.v_bstr_raw_spec RSEGS AD AQ AE L HI -> PQR.make_ec_spec RSEGS AD AQ L HI ->
  getr R2 (PMK.reg 21) = Z_to_bv 64 et -> 0 <= et < 256 ->
  getr R2 (PMK.reg 2) = Z_to_bv 64 (sp - 144) -> getr R2 (PMK.reg 8) = Z_to_bv 64 op -> getr R2 (PMK.reg 9) = Z_to_bv 64 oec ->
  getr R2 (PMK.reg 18) = Z_to_bv 64 oa -> getr R2 (PMK.reg 19) = Z_to_bv 64 (op + 24) -> getr R2 (PMK.reg 20) = Z_to_bv 64 len ->
  getr R2 (PMK.reg 10) = Z_to_bv 64 ptr -> getr R2 (PMK.reg 11) = Z_to_bv 64 k ->
  (forall x, In x [3; 4; 22; 23; 24; 25; 26; 27]%nat -> getr R2 (PMK.reg x) = getr R (PMK.reg x)) ->
  0 <= k <= len -> k < 2 ^ 26 -> 0 <= len < 2 ^ 64 ->
  ((ptr = 0 /\ k = 0) \/ PGS.in_blk (PQM.mparser_own s2) ptr k) -> L5.defined M2 ptr k ->
  RS (1 + k) M2 s2 sm2 e1 cr2 model2 ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx2 R2 0x460e4 M2 model2) K.
Proof.
ltac2:(KReplay.run1 (kr_t_PnMpRiE ()) ["WithHeap"; "Call"] (Mh_0186_blobs2.kr_b_441 ())). Qed.

