Lemma srli32_run (fx : FPState) Rq Mq (pc : Z) (W : bv 32) (rd rs : bv 5) :
  fetch_word RSEGS (Z_to_bv 64 pc) = Some W -> is_ecall W = false -> decode_any W = Some (ShiftImm ALU_SRL rd rs 32, 4%Z) ->
  rd <> 0%bv -> 0 <= pc -> pc + 4 < 2 ^ 64 ->
  exists v, 0 <= v < 2 ^ 32 /\ msteps RSEGS (@mkst fx Rq (Z_to_bv 64 pc) Mq (seg_rom RSEGS)) (@mkst fx (regupd Rq rd (Z_to_bv 64 v)) (Z_to_bv 64 (pc + 4)) Mq (seg_rom RSEGS)).
