Definition ATE (R3 : bvmap 5 word) (M3 : word -> option byte) (s3 : PQM.mpst) (sm3 : PM.strm) (e3 : bool) (cr3 : credit) (model3 : Model)
           (len et : Z) : Prop :=
  getr R3 (PMK.reg 2) = Z_to_bv 64 (sp - 144) /\ getr R3 (PMK.reg 8) = Z_to_bv 64 op /\ getr R3 (PMK.reg 9) = Z_to_bv 64 oec
  /\ getr R3 (PMK.reg 18) = Z_to_bv 64 oa /\ getr R3 (PMK.reg 19) = Z_to_bv 64 (op + 24) /\ getr R3 (PMK.reg 10) = Z_to_bv 64 1
  /\ getr R3 (PMK.reg 20) = Z_to_bv 64 len /\ getr R3 (PMK.reg 21) = Z_to_bv 64 1
  /\ (forall x, In x [3; 4; 22; 23; 24; 25; 26; 27]%nat -> getr R3 (PMK.reg x) = getr R (PMK.reg x))
  /\ RS 2 M3 s3 sm3 e3 cr3 model3 /\ L5.u8_at RSEGS M3 (sp - 58) et /\ 0 <= et < 256 /\ 0 <= len < 2 ^ 64.

