Lemma EXT_SPAN_post (len et : Z) (fx3 fx4 : FPState) (R3 R4 : bvmap 5 word) (M3 : word -> option byte) (s3 : PQM.mpst) (sm3 : PM.strm)
      (e3 : bool) (cr3 : credit) (model3 : Model) :
  PQV8.read_span_v_specG RSEGS AD L HI 0x46804 -> PNV.v_bstr_raw_spec RSEGS AD AQ AE L HI -> PQR.make_ec_spec RSEGS AD AQ L HI ->
  ATE R3 M3 s3 sm3 e3 cr3 model3 len et ->
