(* [comment removed for export] *)
Definition with_tb (s : PQM.mpst) (x : PM.vstr) : PQM.mpst :=
  PQM.MPST (PQM.p_more s) (PQM.p_done s) (PQM.p_depth s) (PQM.p_src s) x (PQM.p_tg s) (PQM.p_bb s) (PQM.p_bg s)
           (PQM.p_sb s) (PQM.p_sk s) (PQM.p_stk s).
(* [comment removed for export] *)
Definition vs_clear (x : PM.vstr) : PM.vstr := match x with PM.VShort _ => PM.VShort 0 | PM.VLong c _ p => PM.VLong c 0 p end.

Lemma with_tb_own s x : PQM.mparser_own (with_tb s x) = PM.src_own (PQM.p_src s) ++ PQM.mvec_own (PQM.p_sb s) (PQM.p_sk s) ++ PQV8.v8_own (PQM.p_bb s) ++ PM.vs_own x.
Proof.
ltac2:(KReplay.run1 (kr_t_PnTsArm ()) [] (Mh_0186_blobs2.kr_b_552 ())). Qed.
Lemma vs_own_clear x : PM.vs_own (vs_clear x) = PM.vs_own x.
Proof.
ltac2:(KReplay.run1 (kr_t_PnTsArm ()) [] (Mh_0186_blobs2.kr_b_553 ())). Qed.
Lemma pot_textM_clear Ly x : PQM.pot_textM Ly (vs_clear x) = PQM.pot_textM Ly x.
Proof.
ltac2:(KReplay.run1 (kr_t_PnTsArm ()) [] (Mh_0186_blobs2.kr_b_554 ())). Qed.
(* [comment removed for export] *)
Lemma tb_perm s1 st1 LB :
  Permutation (PNRN.mown s1 st1 ++ LB)
              (PM.vs_own (PQM.p_tb s1) ++ (PM.src_own (PQM.p_src s1) ++ PQM.mvec_own (PQM.p_sb s1) (PQM.p_sk s1) ++ PQV8.v8_own (PQM.p_bb s1) ++ NEM.aeown st1 ++ LB)).
Proof.
ltac2:(KReplay.run1 (kr_t_PnTsArm ()) [] (Mh_0186_blobs2.kr_b_555 ())). Qed.

