Lemma rs_frameX (c : Z) (fx1 fx2 : FPState) (R1 R2 : bvmap 5 word) (pc1 pc2 : Z) (M1 M2 : word -> option byte) (model1 : Model)
      (s1 : PQM.mpst) (sm1 : PM.strm) (e1 : bool) (cr1 : credit) (lo hi : Z) :
  RS c M1 s1 sm1 e1 cr1 model1 ->
  msteps RSEGS (@mkst fx1 R1 (Z_to_bv 64 pc1) M1 (seg_rom RSEGS)) (@mkst fx2 R2 (Z_to_bv 64 pc2) M2 (seg_rom RSEGS)) -> mem_grows M1 M2 ->
  (forall i, 0 <= i < 2 ^ 64 -> ~ (lo <= i < hi) -> M2 (Z_to_bv 64 i) = M1 (Z_to_bv 64 i)) -> sp - PQRIK.SCR <= lo -> hi <= sp - 56 -> lo <= hi ->
  (RS c M2 s1 sm1 e1 cr1 model1 -> srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx2 R2 pc2 M2 model1) K) ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx1 R1 pc1 M1 model1) K.
Proof.
ltac2:(KReplay.run1 (kr_t_PnTsArm ()) ["WithHeap"; "Call"] (Mh_0186_blobs2.kr_b_556 ())). Qed.

