Definition ATN (R6 : bvmap 5 word) (M6 : word -> option byte) (s5 : PQM.mpst) (sm5 : PM.strm) (e5 : bool) (cr5 : credit) (model5 : Model)
           (v : Z) : Prop :=
  getr R6 (PMK.reg 2) = Z_to_bv 64 (sp - 144) /\ getr R6 (PMK.reg 8) = Z_to_bv 64 op /\ getr R6 (PMK.reg 9) = Z_to_bv 64 oec
  /\ getr R6 (PMK.reg 18) = Z_to_bv 64 oa /\ getr R6 (PMK.reg 20) = Z_to_bv 64 8 /\ getr R6 (PMK.reg 21) = Z_to_bv 64 255
  /\ (forall x, In x [3; 4; 22; 23; 24; 25; 26; 27]%nat -> getr R6 (PMK.reg x) = getr R (PMK.reg x))
  /\ RS 10 M6 s5 sm5 e5 cr5 model5 /\ PQTSS.binl_at M6 (sp - 104) 0 (PQTSS.wlen v 0) v 0 /\ 0 <= v < 2 ^ 64.

