Lemma wfb_cases fbv lo hi : (fbv = 0 \/ fbv = 2) -> 0 <= lo -> 0 <= hi ->
  (lo = 0 /\ hi = 0 /\ PQTSS.wfb fbv lo hi = 0 /\ PQTSS.wlen lo hi = 0%nat)
  \/ ((lo <> 0 \/ hi <> 0) /\ PQTSS.wfb fbv lo hi = fbv /\ PQTSS.wlen lo hi = (if hi =? 0 then 1%nat else 2%nat) /\ (hi = 0 -> 1 <= lo)).
